// src/components/trading/Trading.js
import React, { useState, useEffect } from 'react';
import { useTheme } from '../../contexts/ThemeContext';
import { tradeAPI, marketAPI } from '../../services/api';

// Словарь для названий инструментов
const INSTRUMENT_NAMES = {
  'BBG004730N88': 'Сбербанк',
  'BBG004730RP0': 'Газпром',
  'BBG00475JZZ6': 'Лукойл',
  'BBG006L8G4H1': 'Яндекс',
  'BBG004S681W1': 'ВТБ',
  'BBG00475K2X9': 'Роснефть',
  'BBG004RVFCY3': 'Магнит',
  'BBG004S683W7': 'Татнефть',
  'BBG004S68B31': 'АЛРОСА'
};

// Словарь для соответствия тикеров FIGI
const TICKER_TO_FIGI = {
  'SBER': 'BBG004730N88',
  'GAZP': 'BBG004730RP0',
  'LKOH': 'BBG00475JZZ6',
  'YNDX': 'BBG006L8G4H1',
  'VTBR': 'BBG004S681W1',
  'ROSN': 'BBG00475K2X9',
  'MGNT': 'BBG004RVFCY3',
  'TATN': 'BBG004S683W7',
  'ALRS': 'BBG004S68B31'
};

export default function Trading() {
  const [orderType, setOrderType] = useState('buy');
  const [selectedAsset, setSelectedAsset] = useState('SBER');
  const [quantity, setQuantity] = useState('');
  const [price, setPrice] = useState('');
  const [assets, setAssets] = useState([]);
  const [loading, setLoading] = useState(false);
  const [marketData, setMarketData] = useState({});
  const { isDark } = useTheme();

  useEffect(() => {
    loadAssetsData();
  }, []);

  useEffect(() => {
    if (selectedAsset) {
      loadMarketData(selectedAsset);
    }
  }, [selectedAsset]);

  const loadAssetsData = async () => {
    try {
      // Загружаем портфель чтобы получить доступные для торговли активы
      const portfolioResponse = await tradeAPI.getPortfolio();
      const portfolio = portfolioResponse.data;
      
      // Создаем список активов для торговли
      const tradingAssets = Object.keys(TICKER_TO_FIGI).map(ticker => ({
        symbol: ticker,
        figi: TICKER_TO_FIGI[ticker],
        name: INSTRUMENT_NAMES[TICKER_TO_FIGI[ticker]] || ticker,
        currentPrice: 0 // Будет обновлено из marketData
      }));

      setAssets(tradingAssets);
      
      // Загружаем данные по первому активу
      if (tradingAssets.length > 0) {
        loadMarketData(tradingAssets[0].symbol);
      }
    } catch (error) {
      console.error('Ошибка загрузки данных активов:', error);
      // Запасные данные
      setAssets([
        { symbol: 'SBER', name: 'Сбербанк', currentPrice: 275.50 },
        { symbol: 'GAZP', name: 'Газпром', currentPrice: 172.30 },
        { symbol: 'LKOH', name: 'Лукойл', currentPrice: 5890.25 },
        { symbol: 'YNDX', name: 'Яндекс', currentPrice: 4650.75 }
      ]);
    }
  };

  const loadMarketData = async (symbol) => {
    try {
      const figi = TICKER_TO_FIGI[symbol];
      if (!figi) return;

      const response = await marketAPI.loadCandles(figi, 1);
      if (response.data && response.data.current_price) {
        setMarketData(prev => ({
          ...prev,
          [symbol]: response.data.current_price
        }));
      }
    } catch (error) {
      console.error(`Ошибка загрузки данных для ${symbol}:`, error);
    }
  };

  const handleSubmitOrder = async (e) => {
    e.preventDefault();
    
    if (!quantity || !price) {
      alert('Пожалуйста, заполните количество и цену');
      return;
    }

    setLoading(true);
    try {
      const figi = TICKER_TO_FIGI[selectedAsset];
      const orderData = {
        figi: figi,
        side: orderType,
        quantity: parseInt(quantity),
        price: parseFloat(price)
      };

      await tradeAPI.executeOrder(orderData);
      alert(`Заказ на ${orderType === 'buy' ? 'покупку' : 'продажу'} ${quantity} акций ${selectedAsset} по цене ${price} ₽ успешно исполнен!`);
      
      // Сбрасываем форму
      setQuantity('');
      setPrice('');
      
    } catch (error) {
      console.error('Ошибка исполнения заказа:', error);
      const errorMessage = error.response?.data?.detail || 'Не удалось исполнить заказ. Проверьте параметры и попробуйте снова.';
      alert(`Ошибка: ${errorMessage}`);
    } finally {
      setLoading(false);
    }
  };

  const selectedAssetData = assets.find(asset => asset.symbol === selectedAsset);
  const currentPrice = marketData[selectedAsset] || selectedAssetData?.currentPrice || 0;

  const getAIRecommendation = (symbol) => {
    const recommendations = {
      'SBER': {
        action: 'buy',
        confidence: 0.87,
        predictedReturn: 0.15,
        reason: 'Сильный восходящий тренд с поддержкой технических индикаторов'
      },
      'GAZP': {
        action: 'hold',
        confidence: 0.78,
        predictedReturn: 0.05,
        reason: 'Стабильная производительность с умеренным ростом'
      },
      'LKOH': {
        action: 'sell',
        confidence: 0.82,
        predictedReturn: -0.08,
        reason: 'Ожидается коррекция после недавнего роста'
      },
      'YNDX': {
        action: 'buy',
        confidence: 0.85,
        predictedReturn: 0.12,
        reason: 'Высокий потенциал роста в технологическом секторе'
      },
      'VTBR': {
        action: 'buy',
        confidence: 0.79,
        predictedReturn: 0.08,
        reason: 'Привлекательная оценка и дивидендная доходность'
      },
      'ROSN': {
        action: 'hold',
        confidence: 0.76,
        predictedReturn: 0.06,
        reason: 'Стабильные денежные потоки в энергетическом секторе'
      },
      'MGNT': {
        action: 'buy',
        confidence: 0.81,
        predictedReturn: 0.10,
        reason: 'Укрепление позиций на розничном рынке'
      },
      'TATN': {
        action: 'hold',
        confidence: 0.74,
        predictedReturn: 0.04,
        reason: 'Стабильная дивидендная политика'
      },
      'ALRS': {
        action: 'buy',
        confidence: 0.83,
        predictedReturn: 0.11,
        reason: 'Рост спроса на алмазы и благоприятная конъюнктура рынка'
      }
    };

    return recommendations[symbol] || {
      action: 'hold',
      confidence: 0.70,
      predictedReturn: 0.03,
      reason: 'Нейтральная рекомендация - требуется дополнительный анализ'
    };
  };

  const getActionColors = (action) => {
    switch (action) {
      case 'buy':
        return {
          bg: isDark ? 'bg-green-500/20 border border-green-500/30' : 'bg-green-50 border border-green-200',
          iconBg: isDark ? 'bg-green-500/30' : 'bg-green-100',
          iconColor: 'text-green-600 dark:text-green-400'
        };
      case 'sell':
        return {
          bg: isDark ? 'bg-red-500/20 border border-red-500/30' : 'bg-red-50 border border-red-200',
          iconBg: isDark ? 'bg-red-500/30' : 'bg-red-100',
          iconColor: 'text-red-600 dark:text-red-400'
        };
      case 'hold':
        return {
          bg: isDark ? 'bg-yellow-500/20 border border-yellow-500/30' : 'bg-yellow-50 border border-yellow-200',
          iconBg: isDark ? 'bg-yellow-500/30' : 'bg-yellow-100',
          iconColor: 'text-yellow-600 dark:text-yellow-400'
        };
      default:
        return {
          bg: isDark ? 'bg-gray-500/20 border border-gray-500/30' : 'bg-gray-50 border border-gray-200',
          iconBg: isDark ? 'bg-gray-500/30' : 'bg-gray-100',
          iconColor: 'text-gray-600 dark:text-gray-400'
        };
    }
  };

  const getActionIcon = (action) => {
    switch (action) {
      case 'buy':
        return (
          <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" />
          </svg>
        );
      case 'sell':
        return (
          <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 17h8m0 0V9m0 8l-8-8-4 4-6-6" />
          </svg>
        );
      case 'hold':
        return (
          <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
          </svg>
        );
      default:
        return null;
    }
  };

  const recommendation = getAIRecommendation(selectedAsset);
  const colors = getActionColors(recommendation.action);

  return (
    <div className="space-y-6">
      <div className={`rounded-3xl p-8 text-white shadow-2xl ${
        isDark
          ? 'bg-gradient-to-r from-green-600 to-cyan-600'
          : 'bg-gradient-to-r from-blue-500 to-purple-600'
      }`}>
        <h1 className="text-3xl font-bold mb-2">Торговля</h1>
        <p className={isDark ? 'text-cyan-100' : 'text-blue-100'}>
          Совершайте сделки с AI-рекомендациями
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Панель торговли */}
        <div className="lg:col-span-1">
          <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
            <h3 className="text-xl font-semibold text-gray-800 dark:text-white mb-4">
              Новая сделка
            </h3>
            
            <form onSubmit={handleSubmitOrder} className="space-y-4">
              {/* Переключатель покупки/продажи */}
              <div className="flex rounded-2xl bg-gray-100 dark:bg-gray-700 p-1">
                <button
                  type="button"
                  onClick={() => setOrderType('buy')}
                  className={`flex-1 py-3 px-4 rounded-2xl text-sm font-semibold transition-all duration-300 ${
                    orderType === 'buy'
                      ? 'bg-green-500 text-white shadow-lg'
                      : 'text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-white'
                  }`}
                >
                  Покупка
                </button>
                <button
                  type="button"
                  onClick={() => setOrderType('sell')}
                  className={`flex-1 py-3 px-4 rounded-2xl text-sm font-semibold transition-all duration-300 ${
                    orderType === 'sell'
                      ? 'bg-red-500 text-white shadow-lg'
                      : 'text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-white'
                  }`}
                >
                  Продажа
                </button>
              </div>

              {/* Выбор актива */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Актив
                </label>
                <select
                  value={selectedAsset}
                  onChange={(e) => setSelectedAsset(e.target.value)}
                  className={`w-full rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:border-transparent transition-all duration-300 ${
                    isDark
                      ? 'bg-gray-700 border-gray-600 text-white focus:ring-cyan-500'
                      : 'border border-gray-300 focus:ring-blue-500'
                  }`}
                >
                  {assets.map((asset) => (
                    <option key={asset.symbol} value={asset.symbol}>
                      {asset.name} ({asset.symbol})
                    </option>
                  ))}
                </select>
              </div>

              {/* Текущая цена */}
              <div className={`p-4 rounded-2xl ${
                isDark ? 'bg-gray-700' : 'bg-gray-100'
              }`}>
                <div className="flex justify-between items-center">
                  <span className="text-sm text-gray-600 dark:text-gray-400">Текущая цена:</span>
                  <span className="text-lg font-bold text-gray-800 dark:text-white">
                    {currentPrice.toLocaleString('ru-RU', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ₽
                  </span>
                </div>
              </div>

              {/* Количество */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Количество акций
                </label>
                <input
                  type="number"
                  value={quantity}
                  onChange={(e) => setQuantity(e.target.value)}
                  placeholder="0"
                  min="1"
                  step="1"
                  className={`w-full rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:border-transparent transition-all duration-300 ${
                    isDark
                      ? 'bg-gray-700 border-gray-600 text-white focus:ring-cyan-500'
                      : 'border border-gray-300 focus:ring-blue-500'
                  }`}
                />
              </div>

              {/* Цена */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Цена за акцию (₽)
                </label>
                <input
                  type="number"
                  value={price}
                  onChange={(e) => setPrice(e.target.value)}
                  placeholder={currentPrice.toFixed(2)}
                  step="0.01"
                  min="0.01"
                  className={`w-full rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:border-transparent transition-all duration-300 ${
                    isDark
                      ? 'bg-gray-700 border-gray-600 text-white focus:ring-cyan-500'
                      : 'border border-gray-300 focus:ring-blue-500'
                  }`}
                />
              </div>

              {/* Сумма */}
              {quantity && price && (
                <div className={`p-4 rounded-2xl ${
                  isDark ? 'bg-blue-500/20 border border-blue-500/30' : 'bg-blue-50 border border-blue-200'
                }`}>
                  <div className="flex justify-between items-center">
                    <span className="text-sm font-medium text-gray-700 dark:text-gray-300">Общая сумма:</span>
                    <span className="text-lg font-bold text-blue-600 dark:text-blue-400">
                      {(quantity * price).toLocaleString('ru-RU', {minimumFractionDigits: 2})} ₽
                    </span>
                  </div>
                </div>
              )}

              {/* Кнопка отправки */}
              <button
                type="submit"
                disabled={loading || !quantity || !price}
                className={`w-full py-3 rounded-2xl font-semibold text-white shadow-lg hover:shadow-xl transform hover:-translate-y-0.5 transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none ${
                  orderType === 'buy'
                    ? 'bg-gradient-to-r from-green-600 to-cyan-600 hover:from-green-700 hover:to-cyan-700'
                    : 'bg-gradient-to-r from-red-600 to-pink-600 hover:from-red-700 hover:to-pink-700'
                }`}
              >
                {loading ? (
                  <div className="flex items-center justify-center">
                    <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
                    Исполнение...
                  </div>
                ) : (
                  `${orderType === 'buy' ? 'Купить' : 'Продать'} ${selectedAsset}`
                )}
              </button>
            </form>
          </div>
        </div>

        {/* AI рекомендации и информация */}
        <div className="lg:col-span-2 space-y-6">
          {/* AI рекомендация */}
          <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
            <h3 className="text-xl font-semibold text-gray-800 dark:text-white mb-4">
              AI Рекомендация для {selectedAssetData?.name}
            </h3>
            <div className={`p-6 rounded-2xl ${colors.bg}`}>
              <div className="flex items-center space-x-4">
                <div className={`p-3 rounded-2xl ${colors.iconBg}`}>
                  <div className={colors.iconColor}>
                    {getActionIcon(recommendation.action)}
                  </div>
                </div>
                <div className="flex-1">
                  <div className="flex justify-between items-start mb-2">
                    <h4 className="text-lg font-bold text-gray-800 dark:text-white">
                      {recommendation.action === 'buy' ? 'Сильная покупка' : 
                       recommendation.action === 'sell' ? 'Рекомендация к продаже' : 'Рекомендация держать'}
                    </h4>
                    <span className={`text-sm px-3 py-1 rounded-full font-semibold ${
                      isDark ? 'bg-white/20 text-white' : 'bg-gray-100 text-gray-700'
                    }`}>
                      {(recommendation.confidence * 100).toFixed(0)}% уверенность
                    </span>
                  </div>
                  <p className="text-gray-600 dark:text-gray-400 mb-3">
                    {recommendation.reason}
                  </p>
                  <div className="flex items-center space-x-6">
                    <div className="flex items-center">
                      <div className="w-32 bg-gray-200 dark:bg-gray-700 rounded-full h-2 mr-3">
                        <div 
                          className="h-2 rounded-full transition-all duration-500"
                          style={{
                            width: `${recommendation.confidence * 100}%`,
                            backgroundColor: recommendation.action === 'buy' ? '#10B981' : 
                                           recommendation.action === 'sell' ? '#EF4444' : '#F59E0B'
                          }}
                        ></div>
                      </div>
                      <span className="text-sm text-gray-600 dark:text-gray-400">Точность</span>
                    </div>
                    <div className={`text-lg font-bold ${
                      recommendation.predictedReturn >= 0 ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'
                    }`}>
                      Прогноз: {recommendation.predictedReturn >= 0 ? '+' : ''}{(recommendation.predictedReturn * 100).toFixed(1)}%
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* График и дополнительная информация */}
          <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
            <h3 className="text-xl font-semibold text-gray-800 dark:text-white mb-4">
              Технический анализ - {selectedAssetData?.name}
            </h3>
            <div className={`h-64 rounded-2xl flex items-center justify-center ${
              isDark ? 'bg-gray-700' : 'bg-gray-100'
            }`}>
              <div className="text-center">
                <span className={isDark ? 'text-gray-400' : 'text-gray-500'}>
                  График цены и технические индикаторы появятся здесь
                </span>
                <p className="text-sm mt-2 text-gray-500 dark:text-gray-400">
                  В будущем здесь будут отображаться свечные графики, RSI, MACD и другие индикаторы
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
